// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ref) public {
        // Initialize the contract
        c.seedMarket(1);
        // Give some ether to the contract for buyDrugs
        vm.deal(address(c), 1 ether);
        // Get free kilo for the caller
        c.getFreeKilo();
        // Simulate time passing to accumulate drugs
        vm.warp(block.timestamp + 86401);
        // Get caller's Kilos before collectDrugs
        uint256 kilosBefore = c.getMyKilo();
        // Get drugs before collect
        uint256 drugsBefore = c.getMyDrugs();
        // Calculate expected newKilo
        uint256 expectedNewKilo = drugsBefore / 86400;
        // Call collectDrugs
        c.collectDrugs(ref);
        // Get caller's Kilos after
        uint256 kilosAfter = c.getMyKilo();
        // Assert that Kilos increased by exactly newKilo (the bug removes old Kilos)
        assertTrue(kilosAfter == kilosBefore + expectedNewKilo, "Kilos should be old plus new");
    }
}

